const payload = $input.first().json;
const studentData = payload.data || {};
const score = Number(studentData.score || 0);
const chapter = studentData.chapter || '';
const chapterNum = Number(studentData.chapterNumber || 0);
const incorrectTopics = studentData.incorrectSubtopics || [];

const needsRemedial = score < 60;
let diagnosticInsights = [];
let actionSteps = [];

if (chapterNum === 6 || chapter.toLowerCase().includes('salt') || chapter.toLowerCase().includes('acid')) {
  diagnosticInsights.push('Form 4 Chapter 6 Diagnostic: Acid, Base and Salt.');
  if (incorrectTopics.some(t => t.toLowerCase().includes('qualitative') || t.toLowerCase().includes('cation'))) {
    diagnosticInsights.push('Identified gap in Cation/Anion Qualitative Analysis (amphoteric Al3+, Pb2+, Zn2+ behaviors).');
    actionSteps.push('Review qualitative analysis flowchart with excess NaOH vs NH3 solutions.');
  }
  if (incorrectTopics.some(t => t.toLowerCase().includes('preparation') || t.toLowerCase().includes('insoluble'))) {
    diagnosticInsights.push('Struggled with double decomposition precipitation for insoluble salts (PbSO4, BaSO4, AgCl).');
    actionSteps.push('Practice precipitation reaction equations and filtration rinse steps.');
  }
} else if (chapterNum === 8 || chapter.toLowerCase().includes('manufactured') || chapter.toLowerCase().includes('alloy')) {
  diagnosticInsights.push('Form 4 Chapter 8 Diagnostic: Manufactured Substances in Industry.');
  diagnosticInsights.push('Concept check on atomic lattice slip planes and alloy hardness.');
  actionSteps.push('Draw and compare atomic arrangements of pure copper vs bronze.');
  actionSteps.push('Memorize the 4 main types of glass and their specific thermal/chemical properties.');
}

if (actionSteps.length === 0) {
  actionSteps.push('Review chapter summary notes in ChemLearn AI student dashboard.');
  actionSteps.push('Retake chapter checkpoint quiz to reinforce conceptual retention.');
}

return [{
  json: {
    studentId: studentData.studentId,
    chapter: chapter || 'SPM Chemistry Form 4',
    chapterNumber: chapterNum || 6,
    score,
    diagnosticSummary: diagnosticInsights.join(' '),
    actionPlan: actionSteps,
    recommendedPracticeIds: ['drill-ch6-01', 'drill-ch8-02']
  }
}];
